def _correlation_groups(search):
    X = search.X
    nrm = np.linalg.norm(X, axis=0)
    nrm[nrm == 0] = 1.0
    Z = X / nrm
    C = np.abs(Z.T @ Z)
    groups = [[j] for j in range(search.p)]
    while True:
        (value, pair) = (0.88, None)
        for (i, a) in enumerate(groups):
            for j in range(i):
                b = groups[j]
                if len(a) + len(b) <= 4:
                    v = C[np.ix_(a, b)].min()
                    if v > value:
                        (value, pair) = (v, (i, j))
        if pair is None:
            return [np.asarray(g) for g in groups]
        (i, j) = pair
        groups[j] += groups.pop(i)
